const it = $input.first().json;
const today = new Date().toISOString().split('T')[0];
const system = [
 — 'You are a senior FCRA compliance analyst for a licensed credit-repair organization.',
 — 'Your role: determine if each negative credit item has a GOOD-FAITH, factual basis for dispute.',
 — 'Rules: (1) Never fabricate inaccuracies. (2) Consider accuracy, verifiability, and obsolescence.',
 — 'Obsolescence: late pays/collections removed 7 yrs from date of first delinquency (§§ 1681c).',
 — 'Unverifiable: if furnisher cannot verify, must be deleted under §§ 1681i(a)(5).',
 — 'If the item appears accurate and current, recommend do_not_dispute.',
 — 'Today: ' + today + '. Return ONLY valid JSON, no markdown.'
].join(' ');
const user = [
 — 'Analyze this negative credit item:',
 — JSON.stringify(it, null, 2),
 — '',
 — 'Return JSON: {"dispute_basis": one of ["inaccurate","incomplete","unverifiable","obsolete","not_mine","identity_theft","none"],',
 — '"fcra_sections": ["15 U.S.C. §§ 1681i", ...], "rationale": string (2-3 sentences),',
 — '"dispute_strategy": string, "confidence": 0.0-1.0, "recommendation": "dispute" or "do_not_dispute"}'
].join('
');
return [{ json: { ...it, anthropic_request: {
 — model: 'claude-opus-4-8',
 — max_tokens: 1024,
 — system,
 — messages: [{ role: 'user', content: user }]
} } }];

const resp = $input.first().json;
const d = $('Build Analysis Prompt').first().json;
const text = (resp.content && resp.content[0] && resp.content[0].text) || '{}';
let verdict;
try { const m = text.match(/\{[\s\S]*\}/); verdict = m ? JSON.parse(m[0]) : {}; }
catch(e) { verdict = {}; }
const recommendation = verdict.recommendation || 'do_not_dispute';
return [{ json: {
  item_id: d.item_id, case_id: d.case_id, bureau: d.bureau,
  dispute_basis: verdict.dispute_basis || 'none',
  fcra_sections: verdict.fcra_sections || [],
  rationale: verdict.rationale || 'Analysis unavailable',
  dispute_strategy: verdict.dispute_strategy || '',
  confidence: typeof verdict.confidence === 'number' ? verdict.confidence : 0,
  recommendation,
  analysis_status: recommendation === 'dispute' ? 'disputable' : 'do_not_dispute'
} }];

const all = $('DB: Save Item Analysis').all().map(i => i.json);
const disputable = all.filter(i => i.analysis_status === 'disputable');
const byBureau = {};
for (const it of disputable) (byBureau[it.bureau] = byBureau[it.bureau] || []).push(it);
return [{ json: { case_id: all.length ? all[0].case_id : null, total_items: all.length,
  disputable_count: disputable.length, bureaus: Object.keys(byBureau),
  strategy_by_bureau: byBureau, stage: 'analyzed' } }];
